// C++98-style unscoped enum
enum Color { black, white, red };
// auto white = false; // Error! 'white' is already in this scope

// C++11-style scoped enum
enum class Vehicle { car, truck, boat };
auto car = true; // OK. 'car' is not in this scope.

Vehicle v = Vehicle::car; // Must use scope resolution

// Demonstrating type safety
if (v == Vehicle::truck) { /* ... */ }
// if (v == 0) // Error! No implicit conversion to int.
